<script setup>import { computed, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ArrowLeft, Eye, EyeOff, Check } from 'lucide-vue-next'; import BrandLogo from '../../components/BrandLogo.vue'; import hero from '../../assets/images/1.png'; const route=useRoute(); const router=useRouter(); const register=computed(()=>route.meta.mode==='register'); const show=ref(false); const submit=()=>router.push('/app')</script>
<template><div class="auth-grid"><div class="auth-art"><RouterLink to="/"><BrandLogo light/></RouterLink><div><span class="eyebrow light">A brighter start begins here</span><h1>Learning made<br>joyful, one step<br>at a time.</h1><ul><li><Check/> Guided daily learning</li><li><Check/> Parent-friendly progress</li><li><Check/> Games children love</li></ul></div><img :src="hero" alt="Happy Edyn learner"></div><div class="auth-panel"><RouterLink to="/" class="back-link"><ArrowLeft/> Back to Edyn</RouterLink><form @submit.prevent="submit"><span class="eyebrow soft">{{register?'Create your family account':'Welcome back'}}</span><h2>{{register?'Let’s start growing.':'Good to see you again.'}}</h2><p>{{register?'Set up your parent account. You’ll add your child next.':'Continue your child’s learning journey.'}}</p><label v-if="register">Your name<input required placeholder="Full name"></label><label>Email address<input required type="email" placeholder="you@example.com"></label><label>Password<div class="password-input"><input required :type="show?'text':'password'" placeholder="At least 8 characters"><button type="button" @click="show=!show"><EyeOff v-if="show"/><Eye v-else/></button></div></label><div class="auth-options"><label><input type="checkbox"> Remember me</label><a href="#">Forgot password?</a></div><button class="button wide">{{register?'Create free account':'Log in'}}</button><p class="auth-switch">{{register?'Already have an account?':'New to Edyn?'}} <RouterLink :to="register?'/login':'/register'">{{register?'Log in':'Create a free account'}}</RouterLink></p></form></div></div></template>
